  const FAC0 = `${FIN}\ndefineix façana() {\n  cub(40, 6, 40)\n}\nfaçana()\nmou(50, 0, 0) façana()`;
  const FAC = `${FIN}\ndefineix façana() {\n  cub(40, 6, 40)\n  repeteix p de 0 a 2 {\n    repeteix f de 0 a 2 {\n      mou(4 + f * 12, -1, 4 + p * 12) finestra()\n    }\n  }\n}\nfaçana()\nmou(50, 0, 0) façana()`;
