  const TANCA = `defineix tanca(n, alçada) {\n  repeteix i de 0 a (n - 1) {\n    mou(i * 12, 0, 0) cub(4, 4, alçada)\n  }\n  mou(0, 1, alçada - 8) cub((n - 1) * 12 + 4, 2, 4)\n}\ntanca(5, 20)\nmou(0, 30, 0) tanca(8, 30)`;
