  const ARBREOK = `defineix arbre(mida) {\n  // tronc\n  cilindre(mida / 4, mida)\n  // copa\n  mou(0, 0, mida) esfera(mida)\n}\narbre(8)\nmou(25, 0, 0) arbre(16)\nmou(60, 0, 0) arbre(24)`;
  const PORTA = `// porta(amplada, alçada): un marc en forma de U invertida\ndefineix porta(amplada, alçada) {\n  cub(4, 6, alçada)\n  mou(amplada - 4, 0, 0) cub(4, 6, alçada)\n  mou(0, 0, alçada) cub(amplada, 6, 4)\n}`;
