  const LFONT = `// font(d): bassa i sortidor; d = diàmetre\ndefineix font(d) {\n  cilindre(d, 2)\n  tub(d, 8, 2)\n  cilindre(4, 14)\n  mou(0, 0, 14) esfera(8)\n}`;
